package builtinai

import "github.com/waltwang/nestworth-go/internal/agentcapability"

func pageOperationDefinition() agentcapability.Definition {
	closed := false
	return agentcapability.Definition{Name: "operate_page_control", Effect: agentcapability.Write, Annotations: &agentcapability.Annotations{OpenWorldHint: &closed}, Description: "Interact with a discovered current business page control through its existing UI handler. Requires Full mode; never grants permission itself. First read_page_content, then use exact snapshotId and targetRef and one advertised action. activate takes no value; set_value takes a string; select_option takes the targetRef of a disclosed option as optionRef. No selectors, HTML, routes or arbitrary events. Fresh state, disabled/readonly/inert, secret boundaries and unresolved reviews are checked. Each operation is single-use; stale/blocked/invalid targets require fresh discovery. dispatched means the event was delivered ONLY, never successful validation, loaded data or financial commit. The returned snapshotId identifies the source observation, not the result. Read fresh state afterward and use authoritative evidence to verify results; pending/busy/error/unknown are not success. Never repeat a financial submission to recover missing or uncertain feedback. unverified/transport failure requires inspection, never retry. Use existing financial validation, preview and confirmation flows; do not bypass them. Controls hidden by assistant modal/expanded mode are blocked. Existing controlled navigation tools remain available for supported destinations.", InputSchema: map[string]any{"type": "object", "properties": map[string]any{"snapshotId": map[string]any{"type": "string"}, "targetRef": map[string]any{"type": "string"}, "action": map[string]any{"type": "string", "enum": []string{"activate", "set_value", "select_option"}}, "value": map[string]any{"type": "string", "maxLength": 2048}, "optionRef": map[string]any{"type": "string"}}, "required": []string{"snapshotId", "targetRef", "action"}, "additionalProperties": false}}
}
